INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(11001, '2 Chronicles 27:7', '2 Chronicles', 27, 7, '&nbsp;د يوتام د بادشاهۍ نورې واقعې، د هغۀ جنګونه او د هغۀ نور کارونه، دا هر څۀ د اِسرائيل او د يهوداه په تاريخ کښې ليکلے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11002, '2 Chronicles 27:8', '2 Chronicles', 27, 8, '&nbsp;يوتام د پينځويشتو کالو وو چې هغه بادشاه شو او هغۀ په يروشلم باندې شپاړس کاله بادشاهى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11003, '2 Chronicles 27:9', '2 Chronicles', 27, 9, '&nbsp;يوتام مړ شو او د داؤد په ښار کښې ښخ شو او د هغۀ زوئ احاز د هغۀ نه پس بادشاه جوړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11004, '2 Chronicles 28:1', '2 Chronicles', 28, 1, '&nbsp;احاز د شلو کالو په عُمر کښې بادشاه شو او هغۀ په يروشلم باندې شپاړس کاله بادشاهى وکړه. هغه د خپل پلار نيکۀ داؤد په شان نۀ وو، او په ځائ د هغې يې هغه کار کولو چې په څۀ مالِک خُدائ ناراضه کېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11005, '2 Chronicles 28:2', '2 Chronicles', 28, 2, '&nbsp;او د اِسرائيل د بادشاهانو په نقش قدم باندې روان وو. هغۀ د بعل د اوسپنې بُتان جوړ کړى وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11006, '2 Chronicles 28:3', '2 Chronicles', 28, 3, '&nbsp;د هنوم په وادۍ کښې يې خوشبويۍ سوزولې او تر دې پورې چې خپل زامن يې هم بُتانو ته د سوزېدونکې نذرانو په توګه قربانى کړل. د هغه خلقو د حرامو رِواجونو نقل يې کولو چې کله بنى اِسرائيليان مخ په وړاندې تلل نو مالِک خُدائ هغه د غېرو قومونو خلق د هغه مُلک نه شړلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11007, '2 Chronicles 28:4', '2 Chronicles', 28, 4, '&nbsp;په علاقائى عبادتخانو کښې، په غرونو، او د سورى د هرې ونې لاندې به احاز قربانۍ پېش کولې او خوشبويۍ يې سوزولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11008, '2 Chronicles 28:7', '2 Chronicles', 28, 7, '&nbsp;يو اِسرائيلى فوجى چې نوم يې زِکرى وو هغۀ د احاز بادشاه زوئ معسياه، د محل مشر عزريقام او القنه ووژل. القنه په بادشاه پسې دوېم سړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11009, '2 Chronicles 28:8', '2 Chronicles', 28, 8, '&nbsp;اګر چې د يهوداه خلق د هغوئ خپل رشته‌دار هم وُو، خو د اِسرائيل لښکر دوه لاکه ښځې او ماشومان قېديان کړل او د ډېر زيات مالِ غنيمت سره يې سامريه ته بوتلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11010, '2 Chronicles 28:9', '2 Chronicles', 28, 9, '&nbsp;د مالِک خُدائ يو پېغمبر چې نوم يې عوبېد وو، هغه د سامريه په ښار کښې اوسېدو. کله چې د اِسرائيل لښکر د يهوداه د قېديانو سره واپس راروان وو نو چې هغوئ ښار ته په ننوتلو وُو نو عوبيد هغوئ له د مِلاوېدو دپاره ور ووتلو او عوبيد ورته ووئيل، ”مالِک خُدائ ستاسو د پلار نيکۀ خُدائ پاک د يهوداه خلقو ته غصه وو او ستاسو په ذريعه يې هغوئ له شکست ورکړو، خو چې تاسو هغوئ څومره په بې‌رحمۍ سره حلال کړى دى نو خُدائ پاک د هغې نه خبر شوے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11011, '2 Chronicles 28:10', '2 Chronicles', 28, 10, '&nbsp;او اوس ستاسو اراده دا ده چې د يروشلم او يهوداه سړى او ښځې خپل غلامان او وينځې جوړې کړئ. ولې تاسو ته پته نشته څۀ چې تاسو د مالِک خُدائ د خپل خُدائ پاک خِلاف ګناهونه هم کړې دى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11012, '2 Chronicles 28:11', '2 Chronicles', 28, 11, '&nbsp;زما دا خبره واورئ. دا قېديان ستاسو وروڼه او خوېندې دى. هغوئ پرېږدئ چې لاړ شى، ګنې مالِک خُدائ به په غصه کښې تاسو له سزا درکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11013, '2 Chronicles 28:12', '2 Chronicles', 28, 12, '&nbsp;د اِفرائيم د قبيلې څلورو مشرانو سړو، د يهوحنان زوئ عزرياه، د مسلموت زوئ برکياه، د سلوم زوئ يحزقياه او د خدلى زوئ عماسا هم د فوجى کاروائۍ مخالفت وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11014, '2 Chronicles 28:13', '2 Chronicles', 28, 13, '&nbsp;هغوئ ووئيل، ”دا قېديان دلته مۀ راولئ. مونږ د مالِک خُدائ خِلاف لويه ګناه کړې ده او هغه مو دومره غصه کړے دے چې مونږ له به سزا راکړى. اوس تۀ داسې نور هم څۀ کول غواړې چې په هغې باندې زمونږ جرم زيات شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11015, '2 Chronicles 28:14', '2 Chronicles', 28, 14, '&nbsp;نو بيا فوجيانو قېديان او مالِ غنيمت هغه خلقو او د هغوئ مشرانو ته حواله کړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11016, '2 Chronicles 28:15', '2 Chronicles', 28, 15, '&nbsp;او هغه څلور سړى د دې دپاره مقرر کړے شول چې قېديانو له د هغه نيولے شوى مالِ غنيمت نه جامې ورکړى. هغوئ ورله د اغوستلو دپاره څپلۍ او جامې ورکړې، د خوراک څښاک ښۀ ډېر څيزونه يې ورکړل او د هغوئ په زخمونو يې د زيتُونو تېل واچول. هغه کسان چې کوم ډېر کمزورى وُو او تلے نۀ شو نو هغوئ يې په خرونو کښېنول او ټول قېديان په يريحو کښې د يهوداه علاقې ته بوتلے شول، کوم چې د کجورو د ونو ښار دے. بيا د اِسرائيل خلق خپل کور سامريه ته راواپس شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11017, '2 Chronicles 28:18', '2 Chronicles', 28, 18, '&nbsp;په هغه وخت کښې فلستيانو د نمرپرېواتۀ په طرف د غرونو په لمن کښې او په جنوبى يهوداه کښې په ښارونو باندې حملې کولې. هغوئ د بيت‌شمس، ايالون، جديروت، شوکو، تمنت او جِمسو ښارونه او ورسره خواوشا علاقو کښې کلى هم قبضه کړل او هلته پاخۀ دېره شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11018, '2 Chronicles 28:19', '2 Chronicles', 28, 19, '&nbsp;احاز بادشاه خپل خلق د بدعملۍ په لار روان کړى وُو او د مالِک خُدائ نافرمانى يې کړې وه نو په دې وجه مالِک خُدائ په يهوداه باندې افتونه راوستل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11019, '2 Chronicles 28:20', '2 Chronicles', 28, 20, '&nbsp;د اسور بادشاه د احاز د مدد په ځائ د هغۀ مخالفت وکړو او هغه يې د تکليف سره مخ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11020, '2 Chronicles 28:21', '2 Chronicles', 28, 21, '&nbsp;نو احاز د مالِک خُدائ د کور، محل او د خلقو د مشرانو د کورونو نه يې سرۀ زر واخستل او د اسور بادشاه له يې ورکړل، خو په دې هم کار ونۀ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11021, '2 Chronicles 28:22', '2 Chronicles', 28, 22, '&nbsp;کله چې مصيبتونه ډېر سخت وُو، نو هغه سړى يعنې احاز د مالِک خُدائ خِلاف د مخکښې نه زياته ګناه وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11022, '2 Chronicles 28:23', '2 Chronicles', 28, 23, '&nbsp;هغۀ د دمشق معبودانو ته قربانۍ پېش کړې، چا چې هغۀ له شکست ورکړے وو. هغۀ ووئيل، ”د شام معبودانو د خپلو بادشاهانو مدد وکړو، نو کۀ زۀ هغوئ ته قربانۍ پېش کړم، نو کېدے شى چې زما هم مدد وکړى.“ نو په دې وجه په هغۀ او د هغۀ په قوم باندې تباهى راغله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11023, '2 Chronicles 28:24', '2 Chronicles', 28, 24, '&nbsp;د دې نه علاوه، هغۀ د خُدائ پاک د کور ټول سامان هم واخستلو او ټوټې ټوټې يې کړو. هغۀ د مالِک خُدائ د کور دروازې بندې کړې او د يروشلم په هر ځائ کښې يې قربان‌ګاه جوړې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11024, '2 Chronicles 28:25', '2 Chronicles', 28, 25, '&nbsp;هغۀ د يهوداه په هر يو ښار کښې علاقائى عبادتخانې جوړې کړې، چرته چې به پردو خُدايانو ته خوشبويۍ سوزولے شوې. نو په دې وجه هغۀ مالِک خُدائ د خپل پلار نيکۀ خُدائ پاک په قهر کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11025, '2 Chronicles 28:26', '2 Chronicles', 28, 26, '&nbsp;د شروع نه واخله تر آخره پورې د هغۀ د بادشاهۍ ټولې واقعې د يهوداه او د اِسرائيل په تاريخ کښې ليکلے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11026, '2 Chronicles 28:27', '2 Chronicles', 28, 27, '&nbsp;احاز بادشاه مړ شو او په يروشلم کښې ښخ شو، خو په شاهى اديره کښې ښخ نۀ شو. د هغۀ زوئ حزقياه د هغۀ نه پس بادشاه جوړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11027, '2 Chronicles 29:1', '2 Chronicles', 29, 1, '&nbsp;حزقياه د پينځويشتو کالو په عُمر کښې د يهوداه بادشاه شو او يو کم دېرش کاله يې په يروشلم باندې بادشاهى وکړه. د هغۀ مور ابياه د زکرياه لور وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11028, '2 Chronicles 29:2', '2 Chronicles', 29, 2, '&nbsp;هغۀ د خپل پلار نيکۀ داؤد په نقشِ قدم باندې روان وو او هغه کار يې کولو چې مالِک خُدائ ورباندې رضا کېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11029, '2 Chronicles 29:3', '2 Chronicles', 29, 3, '&nbsp;د حزقياه د بادشاهۍ د اول کال په وړومبۍ مياشت، هغۀ د مالِک خُدائ د کور دروازې کولاو کړې او مرمت يې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11030, '2 Chronicles 29:4', '2 Chronicles', 29, 4, '&nbsp;هغۀ د مالِک خُدائ د کور نمرخاتۀ طرف ته دربار کښې اِمامان او ليويانو راغونډ کړل', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11031, '2 Chronicles 29:5', '2 Chronicles', 29, 5, '&nbsp;او هلته يې ورته خبرې وکړې. هغۀ وفرمائيل، ”ليويانو تاسو به خپل ځانونه وقف کړئ او د مالِک خُدائ کور به پاک کړئ کوم چې ستاسو د پلار نيکۀ خُدائ پاک دے. د مقدس ځائ نه ټول ناپاکه څيزونه لرې کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11032, '2 Chronicles 29:6', '2 Chronicles', 29, 6, '&nbsp;زمونږ پلار نيکۀ د مالِک خُدائ زمونږ د خُدائ پاک نافرمانه وُو او هغه کار يې کولو چې په څۀ باندې هغه ناراضه کېدو. هغوئ مالِک خُدائ او د هغۀ کور پرېښودو او هغۀ ته يې شا وګرځوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11033, '2 Chronicles 29:7', '2 Chronicles', 29, 7, '&nbsp;هغوئ د ننوتو د کوټې دروازې بندې کړې، ډيوې يې پرېښودې چې مړې شى او خوشبوئى يې نۀ سوزوله او نۀ يې د بنى اِسرائيلو د خُدائ پاک په مقدس ځائ کښې سوزېدونکې نذرانې پېش کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11034, '2 Chronicles 29:8', '2 Chronicles', 29, 8, '&nbsp;نو په دې وجه مالِک خُدائ يهوداه او يروشلم ته غصه دے او چې هغۀ څۀ کړى دى په هغې باندې هر يو کس حېران دے او يرېدلے دے او سپک يې ګڼى. او تاسو ته د دې ډېره ښۀ پته ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11035, '2 Chronicles 29:9', '2 Chronicles', 29, 9, '&nbsp;زمونږ پلار نيکۀ په جنګ کښې وژلے شوى وُو او زمونږ ښځې او بچى قېديان بوتلے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11036, '2 Chronicles 29:10', '2 Chronicles', 29, 10, '&nbsp;اوس ما دا فېصله کړې ده چې د مالِک خُدائ د بنى اِسرائيلو د خُدائ پاک سره يو لوظ وکړم، نو هغه به نور مونږ ته غصه نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11037, '2 Chronicles 29:11', '2 Chronicles', 29, 11, '&nbsp;زما زامنو وخت مۀ ضائع کوئ. تاسو هغه څوک يئ چې مالِک خُدائ د دې دپاره خوښ کړى يئ چې هغۀ ته خوشبوئى وسوزوئ او د هغۀ په عبادت کښې د خلقو مشرى وکړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11038, '2 Chronicles 29:15', '2 Chronicles', 29, 15, '&nbsp;دې سړو خپل ليويان راغونډ کړل او هغوئ ټولو خپل ځانونه پاک کړل. بيا هغوئ د مالِک خُدائ د کور پاکول شروع کړل، هم هغه شان چې څنګه بادشاه حُکم کړے وو. هغوئ په خپل کار کښې د مالِک خُدائ د اصُولو منلو خيال ساتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11039, '2 Chronicles 29:16', '2 Chronicles', 29, 16, '&nbsp;د مالِک خُدائ د کور مقدس کولو دپاره اِمامان دننه لاړل او هغوئ د مالِک خُدائ د کور دربار ته هغه هر څۀ راوويستل کوم چې ناپاک وُو. ليويانو هغه هر څۀ د ښار نه بهر د قِدرون وادۍ ته يوړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11040, '2 Chronicles 29:17', '2 Chronicles', 29, 17, '&nbsp;نو هغوئ د اولې مياشتې په وړومبۍ ورځ مقدس کول شروع کړل، نو هم د دې مياشتې په اتمه ورځ هغوئ د مالِک خُدائ د کور د ننوتلو دروازې پورې ورسېدل. بيا هغوئ په اتۀ نورو ورځو کښې د مالِک خُدائ کور پاک کړو او د وړومبۍ مياشتې په شپاړسمه ورځ يې ټول کار ختم کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11041, '2 Chronicles 29:18', '2 Chronicles', 29, 18, '&nbsp;ليويان لاړل او حزقياه بادشاه ته يې دا خبرې وکړې، ”مونږ د مالِک خُدائ د کور د پاکوالى ټول رسم پوره کړے دے، چې په هغې کښې د سوزېدونکې نذرانو قربان‌ګاه، د مقدسې روټۍ مېز او د هغې ټول سامان هم شامل دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11042, '2 Chronicles 29:19', '2 Chronicles', 29, 19, '&nbsp;مونږ هغه ټول سامان هم واپس راوړے دے چې کوم احاز بادشاه د خپلې بادشاهۍ په وخت کښې اوړے وو چې کله هغه د خُدائ پاک نافرمانه وو او مونږ دا بيا وقف کړے دے. دا هر څۀ د مالِک خُدائ د قربان‌ګاه په مخکښې دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11043, '2 Chronicles 29:20', '2 Chronicles', 29, 20, '&nbsp;نو حزقياه سحر وختى د ښار مشران سړى راغونډ کړل او هغوئ په يو ځائ د مالِک خُدائ کور ته لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11044, '2 Chronicles 29:21', '2 Chronicles', 29, 21, '&nbsp;د شاهى خاندان او د يهوداه د خلقو د ګناه د کفارې دپاره او د مالِک خُدائ د کور د پاکولو دپاره، هغوئ اووۀ غوَيى، اووۀ ګډان، اووۀ ګډُورى او اووۀ چېلى د يوې نذرانې په توګه بوتلل. بادشاه د هارون د اولاد اِمامانو ته ووئيل چې هغه ځناور په قربان‌ګاه باندې قربانى کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11045, '2 Chronicles 29:22', '2 Chronicles', 29, 22, '&nbsp;اِمامانو اول غوَيان حلال کړل، بيا يې ګډان او بيا يې ګډُورى حلال کړل او د هرې قربانۍ وينه يې په قربان‌ګاه باندې وشيندله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11046, '2 Chronicles 29:23', '2 Chronicles', 29, 23, '&nbsp;په آخر کښې هغوئ بادشاه او نورو عبادت کوونکو له چېلى راوستل، چې هغوئ خپل لاسونه په دې چېلو باندې کېښودل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11047, '2 Chronicles 29:24', '2 Chronicles', 29, 24, '&nbsp;اِمامانو بيا چېلى حلال کړل او د دې وينه يې په قربان‌ګاه توئ کړه چې دا د ټولو خلقو د ګناه د کفارې نذرانه شى، ځکه چې بادشاه حُکم کړے وو چې د ټول اِسرائيل دپاره سوزېدونکې نذرانې او د ګناه نذرانې پېش شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11048, '2 Chronicles 29:25', '2 Chronicles', 29, 25, '&nbsp;بادشاه په هغه اصُولو باندې عمل وکړو چې کوم مالِک خُدائ د بادشاه پېغمبر جاد او د ناتن پېغمبر په ذريعه داؤد بادشاه ته ښودلى وُو، هغۀ د مالِک خُدائ په کور کښې د ربابونو او چمټو سره ليويان مقرر کړل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11049, '2 Chronicles 29:26', '2 Chronicles', 29, 26, '&nbsp;دا د موسيقۍ هم هغه شان څيزونه وُو چې څنګه داؤد بادشاه استعمال کړى وُو. هلته اِمامان هم د بيګلو سره ولاړ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11050, '2 Chronicles 29:27', '2 Chronicles', 29, 27, '&nbsp;حزقياه حُکم وکړو چې سوزېدونکې نذرانه دې پېش کړے شى، او چې څنګه د نذرانې پېش کېدل شروع شول، نو خلقو د مالِک خُدائ ثناء صِفت وئيل شروع کړل او موسيقارانو د بيګلو او نورو څيزونو غږول شروع کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11051, '2 Chronicles 29:28', '2 Chronicles', 29, 28, '&nbsp;هلته چې هر څوک هم وو نو هغوئ په عبادت کښې شريک شُو او ثناء صِفت وکړو او نوره موسيقى تر هغه وخت پورې جارى وه چې ټولې نذرانې وسوزولے شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11052, '2 Chronicles 29:29', '2 Chronicles', 29, 29, '&nbsp;بيا حزقياه بادشاه او ټول خلق ټيټ شول او د خُدائ پاک عبادت يې وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11053, '2 Chronicles 29:30', '2 Chronicles', 29, 30, '&nbsp;بادشاه د قوم مشرانو ليويانو ته وفرمائيل چې د مالِک خُدائ د ثناء صِفت هغه سندرې ووايئ کومې چې د داؤد او د آسف پېغمبر په ذريعه ليکلے شوې وې. نو هر يو د لوئې خوشحالۍ سره او سندرې ووئيلې هغوئ د خُدائ پاک په وړاندې په زنګنونو او ټيټ شول او د هغۀ عبادت يې وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11054, '2 Chronicles 29:31', '2 Chronicles', 29, 31, '&nbsp;حزقياه خلقو ته وفرمائيل، ”اوس چې تاسو پاک شوئ، نو د مالِک خُدائ کور ته قربانۍ او د شکرانې نذرانې راوړئ.“ نو خلقو خپلې قربانۍ او د شکرانې نذرانې راوړې او چا چې غوښتل نو هغوئ سوزېدونکې نذرانې هم راوړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11055, '2 Chronicles 29:32', '2 Chronicles', 29, 32, '&nbsp;هغوئ مالِک خُدائ ته د سوزېدونکې نذرانې په توګه اويا غوَيى، سل ګډان او دوه سوه ګډُورى راوستل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11056, '2 Chronicles 29:33', '2 Chronicles', 29, 33, '&nbsp;هغوئ شپږ سوه غوَيى او درې زره ګډان هم راوستل چې د خلقو د خوړلو دپاره قربانى شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11057, '2 Chronicles 29:34', '2 Chronicles', 29, 34, '&nbsp;خو اِمامان دومره لږ وُو چې دا ټول ځناور يې نۀ شول حلالولے، نو ليويانو د کار د ختمېدو پورې د هغوئ مدد کولو تر هغه وخته پورې چې نورو اِمامانو ځانونه پاک کړل. ليويانو د ځان په پاک ساتلو کښې د اِمامانو نه زيات خيال ساتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11058, '2 Chronicles 29:35', '2 Chronicles', 29, 35, '&nbsp;د پوره سوزېدونکو نذرانو د پېش کېدو نه علاوه، اِمامان د هغه وازګې د سوزولو هم ذمه وار وُو کومه چې د هغه نذرانو نه پېش کړے شوې وه چې خلقو خوړلې وه او هغوئ د هغه ميو د تويولو هم ذمه وار وُو چې د سوزېدونکې نذرانو سره پېش کړے شوى وُو. نو داسې د مالِک خُدائ په کور کښې عبادت بيا شروع شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11059, '2 Chronicles 29:36', '2 Chronicles', 29, 36, '&nbsp;حزقياه بادشاه او خلق خوشحاله وُو، ځکه چې خُدائ پاک د هغوئ مدد کړے وو چې هر څۀ زر زر وشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11060, '2 Chronicles 30:4', '2 Chronicles', 30, 4, '&nbsp;نو دا خبره بادشاه او نورو خلقو ته ښۀ ښکاره شوه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11061, '2 Chronicles 30:5', '2 Chronicles', 30, 5, '&nbsp;نو هغوئ په شمال کښې د دان نه واخله په جنوب کښې د بيرسبع پورې ټول اِسرائيل له دعوت ورکړو، چې په يروشلم کښې په دومره لوئ شمېر کښې راغونډ شى چې مخکښې نۀ وى راغونډ شوى او د قانون په مطابق د فسحې اختر وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11062, '2 Chronicles 30:6', '2 Chronicles', 30, 6, '&nbsp;نو پېغام وړُونکى د بادشاه او د هغۀ د آفسرانو په حُکم د دې دعوت سره ټول يهوداه او اِسرائيل ته لاړل، ”اے بنى اِسرائيلو، تاسو د اسور بادشاهانو نه بچ شوى يئ چې کله هغوئ مُلک قبضه کړے وو. نو اوس مالِک خُدائ ته راوګرځئ، کوم چې د اِبراهيم، اِسحاق او يعقوب خُدائ پاک دے او هغه به تاسو ته راوګرځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11063, '2 Chronicles 30:7', '2 Chronicles', 30, 7, '&nbsp;د خپل پلار نيکۀ او د خپلوانو په شان مۀ جوړېږئ څوک چې د مالِک خُدائ د هغوئ د خُدائ پاک وفادار نۀ وُو. لکه څنګه چې تاسو ته پته ده چې هغوئ له يې سخته سزا ورکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11064, '2 Chronicles 30:8', '2 Chronicles', 30, 8, '&nbsp;د هغوئ په شان ضدى مۀ جوړېږئ، خو د مالِک خُدائ تابعدارى کوئ. په يروشلم کښې د مالِک خُدائ کور ته راځئ، کوم چې مالِک خُدائ ستاسو خُدائ پاک د همېشه دپاره مقدس کړے دے او د هغۀ عبادت کوئ نو داسې به د هغۀ د سخت قهر نه خلاص شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11065, '2 Chronicles 30:9', '2 Chronicles', 30, 9, '&nbsp;کۀ تاسو مالِک خُدائ ته راوګرځئ، نو چا چې ستاسو خپلوان اغوا کړى دى نو هغوئ به ستاسو په خپلوانو باندې رحم وکړى او هغوئ به خپلو کورونو ته بيا راولى. مالِک خُدائ، خُدائ پاک رحمان او رحيم دے او کۀ تاسو هغۀ ته راوګرځئ، نو هغه به تاسو قبول کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11066, '2 Chronicles 30:10', '2 Chronicles', 30, 10, '&nbsp;پېغام‌وړونکى په شمال کښې د زبولون قبيلې پورې د اِفرائيم او منسى قبيلو په علاقې کښې هر يو ښار ته لاړل، خو خلقو په هغوئ پورې خندل او ټوقې يې ورپورې کولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11067, '2 Chronicles 30:11', '2 Chronicles', 30, 11, '&nbsp;خو بيا هم د آشر، منسى او د زبولون قبيلو څۀ خلقو عاجزى ښکاره کړه او يروشلم ته لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11068, '2 Chronicles 30:12', '2 Chronicles', 30, 12, '&nbsp;خُدائ پاک د يهوداه خلق هم د دې دپاره متحد کړل چې د هغۀ په مرضۍ باندې روان شى او د بادشاه او د هغۀ د آفسرانو حُکمونه ومنى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11069, '2 Chronicles 30:13', '2 Chronicles', 30, 13, '&nbsp;په دوېمه مياشت کښې د خلقو يو لوئ شمېر په يروشلم کښې راغونډ شو چې د پتيرې روټۍ اختر وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11070, '2 Chronicles 30:14', '2 Chronicles', 30, 14, '&nbsp;هغوئ هغه ټولې قربان‌ګاه واخستلې کومې چې په يروشلم کښې د نذرانو د پېش کولو او د خوشبويۍ د سوزولو دپاره استعمالېدلې او د قِدرون په وادۍ کښې يې وغورزولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11071, '2 Chronicles 30:15', '2 Chronicles', 30, 15, '&nbsp;او د هغه مياشتې په څوارلسمه ورځ هغوئ د فسحې اختر د قربانۍ دپاره ګډُورى حلال کړل. کوم اِمامان او ليويان چې پاک نۀ وُو نو هغوئ دومره وشرمېدل چې خپل ځانونه يې مالِک خُدائ ته وقف کړل، نو داسې هغوئ د مالِک خُدائ په کور کښې سوزېدونکې نذرانې پېش کولے شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11072, '2 Chronicles 30:16', '2 Chronicles', 30, 16, '&nbsp;هغوئ د خُدائ پاک د خِدمتګار موسىٰ د شريعت په مطابق د مالِک خُدائ په کور کښې په خپلو ځايونو باندې ودرېدل. ليويانو د قربانۍ وينه اِمامانو له ورکړه، چې هغوئ دا په قربان‌ګاه باندې وشيندله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11073, '2 Chronicles 30:17', '2 Chronicles', 30, 17, '&nbsp;په دغه مجمه کښې ډېر خلق په اودس کښې نۀ وُو، نو په دې وجه هغوئ د فسحې اختر ګډُورى نۀ شُو حلالولے، نو ليويانو د هغوئ دپاره حلال کړل او هغه ګډُورى يې مالِک خُدائ ته وقف کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11074, '2 Chronicles 30:18', '2 Chronicles', 30, 18, '&nbsp;د دې نه علاوه، هغه ډېر کسان کوم چې د اِفرائيم، منسى، يساکار او زبولون د قبيلو نه راغلى وُو نو هغوئ د پاکوالى رسم نۀ وو ادا کړے، نو هغوئ په غلطه طريقه باندې د فسحې اختر کولو. حزقياه بادشاه د هغوئ دپاره دا دُعا وکړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11075, '2 Chronicles 30:19', '2 Chronicles', 30, 19, '&nbsp;”اے مالِکه خُدايه، زمونږ د پلار نيکۀ خُدايه پاکه. د خپل رحم په وجه هغه کسان معاف کړه چې هغوئ د زړۀ د اخلاصه ستا عبادت کوى، اګر چې هغوئ پاک هم نۀ دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11076, '2 Chronicles 30:20', '2 Chronicles', 30, 20, '&nbsp;مالِک خُدائ د حزقياه دُعا واورېدله، هغۀ هغه خلق معاف کړل او هغوئ ته يې څۀ نقصان ونۀ رسولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11077, '2 Chronicles 30:21', '2 Chronicles', 30, 21, '&nbsp;کوم خلق چې په يروشلم کښې راغونډ شوى وُو نو هغوئ د لوئې خوشحالۍ سره اووۀ ورځې د پتيرې روټۍ اختر کولو او ليويانو او اِمامانو هره ورځ د جذبې سره د مالِک خُدائ ثناء صِفت کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11078, '2 Chronicles 30:22', '2 Chronicles', 30, 22, '&nbsp;حزقياه د ليويانو دا صِفت وکړو ځکه چې هغوئ د مالِک خُدائ په عبادت کښې تکړه وُو. دوېم ځل خوشحالى کول د هغه اوو ورځو نه پس په کومو کښې چې هغوئ د مالِک خُدائ په ثناء صِفت کښې قربانۍ پېش کړې وې، چې کوم د هغوئ د پلار نيکۀ خُدائ پاک دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11079, '2 Chronicles 30:23', '2 Chronicles', 30, 23, '&nbsp;هغوئ ټولو دا فېصله وکړه چې اووۀ ورځې به نور اختر کوى. نو هغوئ د خوشحالۍ سره اختر وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11080, '2 Chronicles 30:24', '2 Chronicles', 30, 24, '&nbsp;حزقياه بادشاه يو زر غوَيى او اووۀ زره ګډان خلقو له ورکړل چې حلال يې کړى او وې خورى او آفسرانو هغوئ له يو زر نور غوَيى او لس زره ګډان ورکړل. نو داسې د ډېرو اِمامانو د پاکوالى رسم ادا شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11081, '2 Chronicles 30:25', '2 Chronicles', 30, 25, '&nbsp;نو دا ټول خوشحاله وُو، د يهوداه خلق، اِمامان، ليويان، هغه خلق چې کوم د شمالى طرف نه راغلى وُو او هغه مسافر کوم چې په اِسرائيل او يهوداه کښې پاخۀ دېره شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11082, '2 Chronicles 30:26', '2 Chronicles', 30, 26, '&nbsp;د يروشلم ښار د خوشحالۍ نه ډک وو، ځکه چې د داؤد زوئ سليمان د وخت نه پس هيڅکله هم داسې نۀ وُو شوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11083, '2 Chronicles 30:27', '2 Chronicles', 30, 27, '&nbsp;اِمامانو او ليويانو د خلقو دپاره د مالِک خُدائ برکت وغوښتلو. خُدائ پاک په آسمان کښې په خپل کور کښې د هغوئ دُعاګانې واورېدلې او قبولې يې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11084, '2 Chronicles 31:1', '2 Chronicles', 31, 1, '&nbsp;د اختر د ختمېدو نه پس، ټول اِسرائيليان د يهوداه هر يو ښار ته لاړل، او د کاڼو ستنې يې ماتې کړې، د اشيرې بُت نښې يې راوغورزولې او قربان‌ګاه او علاقائى عبادتخانې يې تباه کړې. هغوئ په باقى ټوله يهوداه کښې، د بنيامين، اِفرائيم او منسى په علاقو کښې هم دغه شان وکړل، بيا هغوئ ټول کورونو ته راواپس شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11085, '2 Chronicles 31:2', '2 Chronicles', 31, 2, '&nbsp;حزقياه بادشاه د اِمامانو او ليويانو تنظيم هم بيا جوړ کړو، چې د هغې لاندې هر يو خپلې خاص ذمه وارۍ لرلې. په دې کښې د سوزېدونکو نذرانو او د سلامتۍ د نذرانو پېش کول، او د مالِک خُدائ د کور په دروازو کښې ثناء صِفت کول او شُکر ادا کول هم شامل وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11086, '2 Chronicles 31:3', '2 Chronicles', 31, 3, '&nbsp;هر سحر او هر ماښام به هغۀ د خپلو رَمو او څاروو نه د سوزېدونکې نذرانو دپاره ځناور ورکول او دا ځناور به د سبت په ورځ، د نوې مياشتې په اختر کښې او چې په نورو اخترونو کښې پېش کېدل، کوم چې د مالِک خُدائ په قانون کښې ليکلے شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11087, '2 Chronicles 31:4', '2 Chronicles', 31, 4, '&nbsp;د دې نه علاوه، بادشاه د يروشلم خلقو ته وفرمائيل چې هغه نذرانې راوړى چې دا اِمامانو او ليويانو حق جوړېدو، نو چې داسې هغوئ هر وخت د مالِک خُدائ قانون ته وقف وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11088, '2 Chronicles 31:5', '2 Chronicles', 31, 5, '&nbsp;چې اِسرائيليانو څنګه دا حُکم واورېدو نو هغوئ د خپلو وړومبو غلو، ميو، د زيتُونو تېلو، شاتو او د نور پېداوار تُحفې راوړې او چې هغوئ څۀ هم لرل د هغې لسمه برخه يې هم راوړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11089, '2 Chronicles 31:6', '2 Chronicles', 31, 6, '&nbsp;کوم خلق چې د يهوداه په ښارونو کښې اوسېدل نو هغوئ ټولو د خپلو څاروو او ګډو، لسمه حِصه راوړه او هغوئ ډېرې زياتې تُحفې هم راوړې، چې هغه يې مالِک خُدائ خپل خُدائ پاک ته وقف کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11090, '2 Chronicles 31:7', '2 Chronicles', 31, 7, '&nbsp;په درېمه مياشت کښې د تُحفو راتلل شروع شول او تر ورپسې څلورو مياشتو پورې د دې نه ډېرى جوړېدل شروع وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11091, '2 Chronicles 31:8', '2 Chronicles', 31, 8, '&nbsp;کله چې حزقياه بادشاه او د هغۀ آفسران راغلل او دا لوئ ډېرى يې وليدل، نو هغوئ د مالِک خُدائ ثناء صِفت وکړو او د خپلو اِسرائيليانو صِفت يې هم وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11092, '2 Chronicles 31:9', '2 Chronicles', 31, 9, '&nbsp;بادشاه د اِمامانو او ليويانو سره د دې تُحفو په حقله خبره وکړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11093, '2 Chronicles 31:10', '2 Chronicles', 31, 10, '&nbsp;او د صدوق د اولاد يو کس، مشر اِمام عزرياه هغۀ ته ووئيل، ”خلقو خپلې تُحفې د مالِک خُدائ کور ته راوړل شروع کړى دى، نو په دې وجه دا د خوراک دپاره کافى دى او د دې نه علاوه دا ډېر زيات هم دى. دا هر څۀ مونږ سره ځکه زيات پاتې شوى دى چې مالِک خُدائ خپلو خلقو له برکت ورکړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11094, '2 Chronicles 31:11', '2 Chronicles', 31, 11, '&nbsp;د بادشاه په حُکم هغوئ د مالِک خُدائ په کور کښې ګودامونه جوړ کړل', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11095, '2 Chronicles 31:12', '2 Chronicles', 31, 12, '&nbsp;او ټولې تُحفې او لسمې حِصې يې د امانت په توګه کېښودې. هغوئ يو ليوى مشر مقرر کړو چې نوم يې کنعنياه وو او د هغۀ ورور سِمعى يې د هغۀ مددګار جوړ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11096, '2 Chronicles 31:13', '2 Chronicles', 31, 13, '&nbsp;دې لسو ليويانو ته د هغوئ د اختيار لاندې کار کول حواله شوے وو: يحى‌ايل، عززياه، نحت، عساهيل، يريموت، يوزبد، اِلى‌ايل، اِسماکياه، محت، او بناياه. دا هر څۀ د حزقياه بادشاه او د مشر اِمام عزرياه د اختيار لاندې شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11097, '2 Chronicles 31:14', '2 Chronicles', 31, 14, '&nbsp;يو ليوى، د يمنه زوئ قورې څوک چې د مالِک خُدائ د کور د نمرخاتۀ طرف ته دروازې مشر څوکيدار وو، هغه د هغه تُحفو د وصولولو او د تقسيمولو مشر وو چې کومې مالِک خُدائ ته پېش کېدلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11098, '2 Chronicles 31:15', '2 Chronicles', 31, 15, '&nbsp;په هغه نورو ښارونو کښې چې چرته اِمامان اوسېدل، په دې کار کښې په وفادارۍ سره دې ليويانو د هغۀ مدد کولو: عدن، مينامين، يشوَع، سمعياه، امرياه او سکانياه. هغوئ په خپلو ليويانو باندې خوراک په وړو او غټو يو شان تقسيمولو هم هغه شان چې څنګه د هغوئ ذمه وارى وه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11099, '2 Chronicles 31:16', '2 Chronicles', 31, 16, '&nbsp;خو دا تقسيم د ډلو په مطابق نۀ وو. هغوئ هغه ټولو سړو له يوه برخه ورکوله چې د هغوئ عُمر درې کاله يا د دې نه زيات وو د کومو چې د خپلو عُهدو په مطابق د مالِک خُدائ په کور کښې د هرې ورځې ذمه وارۍ لرلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(11100, '2 Chronicles 31:17', '2 Chronicles', 31, 17, '&nbsp;اِمامانو ته د ډلو په مطابق ذمه وارۍ حواله شوې وې او هغه ليويانو ته د کار د ډلو په مطابق ذمه وارۍ حواله شوې وې چې د هغوئ عُمر شل کاله يا د دې نه زيات وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');